    def activity(self):
        tankls = dm().available_tank_reporting()
        print("ALL TANKS: ", tankls)

        for tank in tankls:
            data = dm().tank_basic_report(tank)
            print("VOL: ", data[2], "DATE: ", data[0])

            tablerow = self.table_show_existing_tank.rowCount()
            self.table_show_existing_tank.insertRow(tablerow) #its a must

            self.table_show_existing_tank.setItem(tablerow, 0, QtWidgets.QTableWidgetItem(tank))
            self.table_show_existing_tank.setItem(tablerow, 1, QtWidgets.QTableWidgetItem(str(data[2])))
            self.table_show_existing_tank.setItem(tablerow, 2, QtWidgets.QTableWidgetItem(data[0]))

    def deleterow(self):
        row= self.table_show_existing_tank.currentIndex().row()
        item = self.table_show_existing_tank.item(row, 0).text()

        cell_id = self.table_show_existing_tank.currentRow()
        self.table_show_existing_tank.removeRow(cell_id)

        print("Deleted Table: ", item)
        dm().tank_data_unregister(item)

    def msgBox(self,boxtitle, message, myicon):
        msg = QtWidgets.QMessageBox()
        msg.setIcon(myicon)
        msg.setText(message)
        msg.setWindowTitle(boxtitle)
        msg.setStandardButtons(QtWidgets.QMessageBox.Ok | QtWidgets.QMessageBox.Cancel)
        msg.setFont(QFont("Baloo Da 2",12))
        
        x = msg.exec_()
        return x

    def confirmation(self):
        row = self.table_show_existing_tank.currentIndex().row()
        item = self.table_show_existing_tank.item(row, 0).text()


        #error handling - [empty table row]
        box = self.msgBox("Tank Selection Check", "আপনি কি {} এর নিবন্ধন বাতিল করেত চান?".format(item), QMessageBox.Warning)
        if box == 1024:
            self.popup()    
        else:
            return 

    def popup(self):
        win = QWidget()

        # all widgets
        lay = QVBoxLayout()
        btn = QPushButton("নিশ্চিত করুন")
        lbl = QLabel("পাসওয়ার্ড")
        txt = QLineEdit()

        # widget modification
        txt.setPlaceholderText("আপনার পাসওয়ার্ড লিখুন")
        txt.setValidator(QIntValidator())
        txt.setFixedSize(300,30)
        txt.setFont(QFont("Baloo Da 2",12))

        lbl.setFixedSize(300,80)
        lbl.setAlignment(Qt.AlignLeft)
        lbl.setFont(QFont("Baloo Da 2",30))


        btn.clicked.connect(lambda: self.passchecker2(win, txt))
     

        btn.setFont(QFont("Baloo Da 2",12))


        # setting the widget into the layout
        lay.addWidget(lbl)
        lay.addWidget(txt)
        lay.addWidget(btn)
        lay.setAlignment(Qt.AlignCenter)

        # set the layout in the main application window
        win.setLayout(lay)
        win.show()

    def passchecker2(self, win, txt):

        info = txt.text()
        if info == '1234': # password matching
            print("Bingo!!")
            
            self.deleterow()

            txt.clear()
            self.msgBox("Tank Selection Checker","নিবন্ধন বাতিল সম্পন্ন হয়েছে!", QtWidgets.QMessageBox.Information)
            win.hide()

        else:
            print("Failed!")
            txt.clear()
            self.msgBox("Tank Selection Checker","আপনি ভুল পাসওয়ার্ড দিয়েছেন। আবার চেষ্টা করুন।", QtWidgets.QMessageBox.Warning)

